import numpy as np, warnings, io, os, tempfile
warnings.simplefilter("ignore")
print(np.__version__)
def P(label, f):
    try:
        r = f()
        print(f"[{label}] OK:", repr(r).replace("\n", " ")[:400])
    except Exception as e:
        print(f"[{label}] EXC: {type(e).__name__}: {e}".replace("\n", " ")[:400])
fmt = np.lib.format
def rt(arr, **kw):
    b = io.BytesIO(); fmt.write_array(b, arr, **kw); b.seek(0); return fmt.read_array(b, allow_pickle=True)
P("rt padded struct", lambda: rt(np.zeros(2, dtype={"names": ["a"], "formats": ["i4"], "offsets": [4], "itemsize": 12})).dtype)
P("rt aligned struct", lambda: rt(np.zeros(1, dtype=np.dtype([("a", "i1"), ("b", "i8")], align=True))).dtype)
P("rt fortran", lambda: rt(np.asfortranarray(np.arange(6).reshape(2, 3))).flags.f_contiguous)
P("rt 0d", lambda: rt(np.array(5)))
P("rt empty struct", lambda: rt(np.zeros(0, dtype="i,f")).dtype)
P("rt version 3 unicode names", lambda: rt(np.zeros(1, dtype=[("é", "i")]), version=(3, 0)).dtype)
P("rt big endian", lambda: rt(np.arange(3, dtype=">i4")).dtype)
P("rt subarray dtype", lambda: rt(np.zeros(2, dtype=("i4", (3,)))).shape)
P("rt titles", lambda: rt(np.zeros(1, dtype=[(("t", "a"), "i4")])).dtype)
P("rt metadata", lambda: rt(np.zeros(1, dtype=np.dtype("i4", metadata={"x": 1}))).dtype.metadata)
P("rt datetime", lambda: rt(np.array(["2020"], "M8[D]")))
P("rt nested empty", lambda: rt(np.zeros(1, dtype=[("a", [])])).dtype)
P("rt object", lambda: rt(np.array([None, {"a": 1}], dtype=object)))
P("rt T", lambda: rt(np.array(["a"], "T")))
P("descr_to_dtype padded", lambda: fmt.descr_to_dtype([("", "|V4"), ("a", "<i4")]))
